<section class="panel"><header class="panel-head"><div><span class="eyebrow">Immutable fulfillment history</span><h2>Operational and financial evidence</h2></div><span class="panel-meta"><?= count($events) ?> event(s)</span></header><div class="timeline"><?php foreach($events as $event): ?><article><small><?= h(date_us(substr((string)$event['created_at'],0,10))) ?><br><?= h(substr((string)$event['created_at'],11,5)) ?></small><div><strong><?= h(status_label($event['event_type'])) ?></strong><p><?= h($event['evidence_note']) ?></p></div><?= badge($event['severity']) ?></article><?php endforeach; ?><?php if(!$events): render_empty_state('No fulfillment events','Supplier acknowledgment, receipts, matches, exceptions, and payment-release decisions will appear here.'); endif; ?></div></section>
